using System;
using ExpenseHub.Api.Domain.Enums;

namespace ExpenseHub.Api.Domain.Entities;

/// <summary>
/// A request for a summary of expenses by period, and the result once it is calculated.
/// The requester, the scope, the period and the state are set by the server; the worker reads them from this record,
/// never from the message.
/// </summary>
public class ReportRequest
{
    /// <summary>Gets or sets the identifier generated by the server.</summary>
    public Guid Id { get; set; }

    /// <summary>Gets or sets the Identity user id of who requested the report, taken from the token.</summary>
    public string RequesterId { get; set; } = string.Empty;

    /// <summary>Gets or sets whose expenses the report adds up.</summary>
    public ReportScope Scope { get; set; }

    /// <summary>Gets or sets the first day of the period, inclusive. It is compared with the date of the expense.</summary>
    public DateOnly FromDate { get; set; }

    /// <summary>Gets or sets the last day of the period, inclusive. It is compared with the date of the expense.</summary>
    public DateOnly ToDate { get; set; }

    /// <summary>Gets or sets the current state. It is a concurrency token, so two attempts cannot make the same transition.</summary>
    public ReportStatus Status { get; set; }

    /// <summary>Gets or sets the UTC instant the request was registered.</summary>
    public DateTimeOffset CreatedAtUtc { get; set; }

    /// <summary>Gets or sets the UTC instant the processing started, once it did.</summary>
    public DateTimeOffset? StartedAtUtc { get; set; }

    /// <summary>Gets or sets the UTC instant the request completed or failed, once it did.</summary>
    public DateTimeOffset? CompletedAtUtc { get; set; }

    /// <summary>
    /// Gets or sets the saved result, as JSON written and read only by <c>ReportResultSerializer</c>. It is set together with
    /// <see cref="ReportStatus.Completed"/>, in the same save.
    /// </summary>
    public string? ResultJson { get; set; }

    /// <summary>Gets or sets the stable code of the error, when the request failed.</summary>
    public string? ErrorCode { get; set; }

    /// <summary>Gets or sets the sanitized message of the error, when the request failed.</summary>
    public string? ErrorMessage { get; set; }
}
